Local Notation zb b := (bv_unsigned b) (only parsing).
Local Notation zbytes bs := (map (@bv_unsigned 8) bs) (only parsing).
Lemma zb_range : forall b : byte, 0 <= bv_unsigned b < 256.
Proof. intros b. pose proof (bv_unsigned_in_range 8 b) as R. unfold bv_modulus in R. cbn in R. lia. Qed.
Lemma win_byte : forall m it0 bs p, bytes_at asegs m it0 bs -> it0 <= p < it0 + Z.of_nat (length bs) ->
  exists b, nth_error bs (Z.to_nat (p - it0)) = Some b.
Proof.
  intros m it0 bs p WIN Hp. destruct (nth_error bs (Z.to_nat (p - it0))) as [b|] eqn:N; [exists b; reflexivity|].
  apply nth_error_None in N. lia.
Qed.

