Lemma memcmp_model_zbytes_zero : forall (ls rs : list byte), length ls = length rs ->
  (memcmp_model (map (@bv_unsigned 8) ls) (map (@bv_unsigned 8) rs) = 0 <-> ls = rs).
Proof.
  intros ls rs L. rewrite memcmp_model_zero by (rewrite !length_map; exact L).
  split; [| intros ->; reflexivity].
  revert rs L. induction ls as [|a ls IH]; intros [|b rs] L E; cbn in *; try reflexivity; try discriminate.
  injection E as E1 E2. f_equal; [apply bv_eq; exact E1 | apply IH; [lia | exact E2]].
Qed.
